#include <vector>
#include <string>
#include <algorithm>

using namespace std;

class Solution {
public:
    bool phonePrefix(vector<string>& numbers) {
        sort(numbers.begin(), numbers.end());
        for (size_t i = 1; i < numbers.size(); ++i) {
            if (numbers[i].rfind(numbers[i - 1], 0) == 0) {
                return false;
            }
        }
        return true;
    }
};

import java.util.*;

class Solution {
    public boolean phonePrefix(String[] numbers) {
        Arrays.sort(numbers);
        for (int i = 1; i < numbers.length; i++) {
            if (numbers[i].startsWith(numbers[i - 1])) {
                return false;
            }
        }
        return true;
    }
}

var phonePrefix = function(numbers) {
    numbers.sort();
    for (let i = 1; i < numbers.length; i++) {
        if (numbers[i].startsWith(numbers[i - 1])) {
            return false;
        }
    }
    return true;
};
